library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

library work;
use work.constants.all;
use work.interfaces.all;

entity toplevel_tb is
--    Port ( I_clock : in STD_LOGIC);
end toplevel_tb;

architecture Behavioral of toplevel_tb is

    signal tb_clk : std_logic := '0';
    signal clk_aux : std_logic := '0';
    signal tb_rst : std_logic := '0';

    signal tb_ok       : std_logic := '0';
    signal tb_nook     : std_logic := '0';
    signal tb_hbeat    : std_logic := '0';
    signal tb_exception: std_logic := '0';

    signal inst : std_logic_vector(XLEN-1 downto 0) := (others => '0');

    signal result : std_logic_vector(XLEN - 1 downto 0);

    -- Clock:
    -- There is a small problem in the test whereby, since the clock does not come from the testbench but the integrated clk_wiz, then the 
    -- simulation starts to drift from the actual time. Therefore below, there are two instances where a cycle is removed. Search for "drift".
    constant CLK_PERIOD : time := 5.05050 ns;

    signal mark : std_logic := '0';

    signal inst_ID,inst_EX,inst_MEM,inst_WB: std_logic_vector(XLEN-1 downto 0) := (others => '0');

    procedure wait_untilEndOfTestCase is
    begin
        wait for CLK_PERIOD;wait for CLK_PERIOD;wait for CLK_PERIOD;wait for CLK_PERIOD;    -- For the actual output of the processor.
        wait for CLK_PERIOD;--wait for CLK_PERIOD;                                            -- To get out of the test environment.
    end procedure wait_untilEndOfTestCase;

begin

    uut: entity work.toplevel
        port map (
            clk         => clk_aux,
            rst         => tb_rst,
            O_result    => result,
            O_ok        => tb_ok,
            O_nook      => tb_nook,
            O_heartbeat => tb_hbeat,
            O_exception => tb_exception
        );

    -- Clock generation
    clk_aux <=  '0' when tb_rst = '1' else
            not clk_aux after 10ns / 2;
    tb_clk <=  '0' when tb_rst = '1' else
            not tb_clk after CLK_PERIOD / 2;

    inst_ID <= inst     when rising_edge(tb_clk);
    inst_EX <= inst_ID  when rising_edge(tb_clk);
    inst_MEM<= inst_EX  when rising_edge(tb_clk);
    inst_WB <= inst_MEM when rising_edge(tb_clk);

    -- Helper mark generation
    cyclemark_p:process
        variable x: std_logic := '0';
	begin
		if x = '0' then
			wait for 4.2*CLK_PERIOD/2;
			x := '1';
		end if;
		mark <= not mark;
        wait for CLK_PERIOD;
	end process;

    -- Test stimulus process
    process
    begin
        -- Initial reset
        tb_rst <= '1';
        wait for 100ns;
        inst <= NOP;

        wait for 1.1*CLK_PERIOD;
        
--        wait for CLK_PERIOD;
        tb_rst <= '0';
        wait until tb_nook='0';
--        wait for 0.3*CLK_PERIOD;
--        wait until rising_edge(clk);

        -- Test case 000.
        inst <= x"7FF00F93"; -- ADDI "7FF" RS1=X0, RD=X31
--        wait for CLK_PERIOD;
        wait until rising_edge(tb_clk);
        inst <= NOP;         -- This extra cycle is to allow the use of syncrhonous reading of the GPRs, which improves timing (performance).
--        wait for CLK_PERIOD;
        wait until rising_edge(tb_clk); -- Nonetheless, in a real system it would not be needed as there would be a FU unit which would bypass the needed value.
        inst <= x"000F9073"; -- CSRRW CSR=0x000,RS1=X31,RD=X0  ;wo 
--        wait for CLK_PERIOD;
        wait until rising_edge(tb_clk);
        inst <= NOP;
--        wait for CLK_PERIOD;
        wait until rising_edge(tb_clk);
--        inst <= x"00002FF3"; -- CSRRS CSR=0x000,RS1=X0 ,RD=X31 ;ro
        inst <= x"00012FF3"; -- CSRRS CSR=0x000,RS1=X2 ,RD=X31 ;ro ----- In these first 3 tests, we check the correct behaviour of ORing csr_input.
--        wait for CLK_PERIOD;
        wait until rising_edge(tb_clk);

        -- Test case 001.
        inst <= x"00000F93"; -- ADDI "000" RS1=X0, RD=X31
        wait for CLK_PERIOD; inst <= NOP; wait for CLK_PERIOD;
        inst <= x"001F9073"; -- CSRRW CSR=0x001,RS1=X31,RD=X0  ;wo 
        wait for CLK_PERIOD;
        inst <= NOP;
        wait for CLK_PERIOD;
--        inst <= x"00102FF3"; -- CSRRS CSR=0x001,RS1=X0 ,RD=X31 ;ro
        inst <= x"00112FF3"; -- CSRRS CSR=0x001,RS1=X2 ,RD=X31 ;ro
        wait for CLK_PERIOD;

        -- Test case 002.
        inst <= x"00100F93"; -- ADDI "001" RS1=X0, RD=X31
        wait for CLK_PERIOD; inst <= NOP; wait for CLK_PERIOD;
        inst <= x"002F9073"; -- CSRRW CSR=0x002,RS1=X31,RD=X0  ;wo 
        wait for CLK_PERIOD;
        inst <= NOP;
        wait for CLK_PERIOD;
--        inst <= x"00202FF3"; -- CSRRS CSR=0x002,RS1=X0 ,RD=X31 ;ro
        inst <= x"00212FF3"; -- CSRRS CSR=0x002,RS1=X2 ,RD=X31 ;ro
        wait for CLK_PERIOD;

        -- Test case 0x003.
