        wait for CLK_PERIOD; inst <= NOP; wait for CLK_PERIOD; inst <= x"003F9073"; -- CSRRW CSR=0x003,RS1=X31,RD=X0  ;wo 
        wait for CLK_PERIOD;inst <= NOP;wait for CLK_PERIOD;
        inst <= x"00302FF3"; -- CSRRS CSR=0x003,RS1=X0 ,RD=X31 ;ro
        wait for CLK_PERIOD;
        -- Test case 0x004.
        inst <= x"00300F93"; -- ADDI "0x003" RS1=X0, RD=X31
        wait for CLK_PERIOD; inst <= NOP; wait for CLK_PERIOD; inst <= x"004F9073"; -- CSRRW CSR=0x004,RS1=X31,RD=X0  ;wo 
        wait for CLK_PERIOD;inst <= NOP;wait for CLK_PERIOD;
        inst <= x"00402FF3"; -- CSRRS CSR=0x004,RS1=X0 ,RD=X31 ;ro
        wait for CLK_PERIOD;
        -- Test case 0x005.
        inst <= x"00400F93"; -- ADDI "0x004" RS1=X0, RD=X31
        wait for CLK_PERIOD; inst <= NOP; wait for CLK_PERIOD; inst <= x"005F9073"; -- CSRRW CSR=0x005,RS1=X31,RD=X0  ;wo 
        wait for CLK_PERIOD;inst <= NOP;wait for CLK_PERIOD;
        inst <= x"00502FF3"; -- CSRRS CSR=0x005,RS1=X0 ,RD=X31 ;ro
        wait for CLK_PERIOD;
        -- Test case 0x006.
